alter table public.exercicios drop constraint if exists exercicios_categoria_check;
alter table public.exercicios add constraint exercicios_categoria_check
  check (categoria in ($q$forca$q$, $q$core$q$, $q$mobilidade$q$, $q$prevencao$q$, $q$ativacao$q$, $q$pliometria$q$, $q$tecnica$q$));

on conflict (id) do nothing;

on conflict (id) do nothing;
